package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type SchedRec struct {
	ScAcct  string          // PIC X(4) @0 len=4
	ScPrin  decimal.Decimal // PIC 9(5)V99 @4 len=7
	ScRate  decimal.Decimal // PIC 9(2)V99 @11 len=4
	ScYears int64           // PIC 9(1) @15 len=1
}

var WsEofFlag string // PIC X len=1 = "N"
var WsBal decimal.Decimal // PIC 9(8)V99 len=10 = 0
var WsYear int64 // PIC 99 len=2 = 0
var WsCount int64 // PIC 99 len=2 = 0
var WsBalEd string // PIC ZZ,ZZZ,ZZ9.99 len=13

var schedRec SchedRec

var inputLines []string
var inputIdx int
var inputDone bool

func parseNumField(s string, scale int32) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.Zero
	}
	// keep only optional sign and digits
	neg := false
	var b strings.Builder
	for i, c := range s {
		if i == 0 && (c == '+' || c == '-') {
			if c == '-' {
				neg = true
			}
			continue
		}
		if c >= '0' && c <= '9' {
			b.WriteRune(c)
		} else if c == '.' {
			// should not occur, but handle by ignoring
			continue
		}
	}
	digits := b.String()
	digits = strings.TrimLeft(digits, "0")
	if digits == "" {
		return decimal.Zero
	}
	// build integer then shift
	// use decimal from string to avoid overflow, then scale
	// digits is integer; value = digits * 10^-scale
	d, err := decimal.NewFromString(digits)
	if err != nil {
		return decimal.Zero
	}
	d = d.Shift(-scale)
	if neg {
		d = d.Neg()
	}
	return d
}

func parseIntField(s string) int64 {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0
	}
	var b strings.Builder
	for i, c := range s {
		if i == 0 && (c == '+' || c == '-') {
			b.WriteRune(c)
			continue
		}
		if c >= '0' && c <= '9' {
			b.WriteRune(c)
		}
	}
	t := strings.TrimSpace(b.String())
	if t == "" || t == "+" || t == "-" {
		return 0
	}
	var neg bool
	if t[0] == '-' {
		neg = true
		t = t[1:]
	} else if t[0] == '+' {
		t = t[1:]
	}
	t = strings.TrimLeft(t, "0")
	if t == "" {
		return 0
	}
	var v int64
	for _, c := range t {
		v = v*10 + int64(c-'0')
	}
	if neg {
		v = -v
	}
	return v
}

func parseRecord(line string) SchedRec {
	// pad with spaces on right if shorter
	if len(line) < 16 {
		line = line + strings.Repeat(" ", 16-len(line))
	} else if len(line) > 16 {
		line = line[:16]
	}
	var r SchedRec
	r.ScAcct = line[0:4]
	r.ScPrin = parseNumField(line[4:11], 2)
	r.ScRate = parseNumField(line[11:15], 2)
	r.ScYears = parseIntField(line[15:16])
	// keep only low-order digits that fit
	// ScPrin 9(5)V99: total scaled digits 7 -> mod 10^7
	// ScRate 9(2)V99: mod 10^4 ; ScYears mod 10
	// Apply truncation/masking to mimic COBOL storage (values are non-negative in practice)
	sp := r.ScPrin.Shift(2).Truncate(0).IntPart()
	sp = sp % 10000000
	if sp < 0 {
		sp += 10000000
	}
	r.ScPrin = decimal.New(sp, -2)
	sr := r.ScRate.Shift(2).Truncate(0).IntPart()
	sr = sr % 10000
	if sr < 0 {
		sr += 10000
	}
	r.ScRate = decimal.New(sr, -2)
	r.ScYears = r.ScYears % 10
	if r.ScYears < 0 {
		r.ScYears += 10
	}
	return r
}

func storeWsBal(d decimal.Decimal) {
	// truncate to scale 2 then keep low-order digits (10 scaled digits)
	t := d.Truncate(2)
	scaled := t.Shift(2).Truncate(0).IntPart()
	const modBase int64 = 10000000000
	r := scaled % modBase
	WsBal = decimal.New(r, -2)
}

func formatWsBalEd() string {
	// WsBal has scale 2, range fits 9(8)V99 after masking
	v := WsBal.Truncate(2)
	neg := v.IsNegative()
	if neg {
		v = v.Neg()
	}
	scaled := v.Shift(2).Truncate(0).IntPart()
	if scaled < 0 {
		scaled = 0
	}
	scaled = scaled % 10000000000
	intPart := scaled / 100
	fracPart := scaled % 100
	// 8 integer digits
	var d [8]byte
	tmp := intPart
	for i := 7; i >= 0; i-- {
		d[i] = byte(tmp % 10)
		tmp /= 10
	}
	// find first nonzero
	k := -1
	for i := 0; i < 8; i++ {
		if d[i] != 0 {
			k = i
			break
		}
	}
	digits := make([]byte, 8)
	for i := 0; i < 8; i++ {
		digits[i] = '0' + d[i]
	}
	var out [13]byte
	// helper to decide char for digit position idx
	getChar := func(idx int) byte {
		if k == -1 {
			return ' '
		}
		if idx < k {
			return ' '
		}
		return digits[idx]
	}
	// slots
	// 0:d0 1:d1 2:comma 3:d2 4:d3 5:d4 6:comma 7:d5 8:d6 9:d7 10:. 11:f1 12:f2
	out[0] = getChar(0)
	if k == -1 {
		out[0] = ' '
	}
	out[1] = getChar(1)
	// comma 1: printed unless everything to its left and itself region suppressed
	// i.e., space if first nonzero is to the right of it (k > 1)
	if k == -1 || k > 1 {
		out[2] = ' '
	} else {
		out[2] = ','
	}
	out[3] = getChar(2)
	out[4] = getChar(3)
	out[5] = getChar(4)
	if k == -1 || k > 4 {
		out[6] = ' '
	} else {
		out[6] = ','
	}
	out[7] = getChar(5)
	out[8] = getChar(6)
	// 9 is '9' type: always digit
	if k == -1 {
		out[9] = '0'
	} else {
		out[9] = digits[7]
	}
	out[10] = '.'
	out[11] = byte('0' + fracPart/10)
	out[12] = byte('0' + fracPart%10)
	_ = neg // balances are unsigned; ignore sign
	return string(out[:])
}

func formatPIC99(v int64) string {
	v = v % 100
	if v < 0 {
		v += 100
	}
	return fmt.Sprintf("%02d", v)
}

func READPARA() {
	if inputIdx < len(inputLines) {
		schedRec = parseRecord(inputLines[inputIdx])
		inputIdx++
		WsEofFlag = "N"
		inputDone = false
	} else {
		WsEofFlag = "Y"
		inputDone = true
	}
}

func PROCESSPARA() {
	// MOVE SC-PRIN TO WS-BAL
	storeWsBal(schedRec.ScPrin)
	// PERFORM VARYING WS-YEAR FROM 1 BY 1 UNTIL WS-YEAR > SC-YEARS
	WsYear = 1
	for !(WsYear > schedRec.ScYears) {
		// COMPUTE WS-BAL ROUNDED = WS-BAL * (1 + SC-RATE / 100)
		factor := decimal.NewFromInt(1).Add(schedRec.ScRate.Shift(-2))
		prod := WsBal.Mul(factor)
		rounded := prod.Round(2)
		storeWsBal(rounded)
		WsBalEd = formatWsBalEd()
		fmt.Printf("%s Y%s %s\n", schedRec.ScAcct, formatPIC99(WsYear), WsBalEd)
		WsYear++
		// PIC 99 wraps
		WsYear = WsYear % 100
		if WsYear < 0 {
			WsYear += 100
		}
		// careful: wrapping could cause infinite loop for large SC-YEARS, but SC-YEARS is 0-9 so fine
		// To avoid wrap-around infinite loop, break if wrapped to 0 and still <= years (should not happen)
		// The COBOL varying would wrap as well; keep simple
	}
	WsBalEd = formatWsBalEd()
	fmt.Printf("%s FINAL %s\n", schedRec.ScAcct, WsBalEd)
	WsCount = (WsCount + 1) % 100
	READPARA()
}

func MAINPARA() {
	// OPEN INPUT SCHED-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		// empty input behaves as immediate EOF
		inputLines = nil
	} else {
		sc := bufio.NewScanner(f)
		// allow long lines
		sc.Buffer(make([]byte, 1024*1024), 1024*1024)
		for sc.Scan() {
			line := sc.Text()
			// strip trailing \r (Scanner already strips \n; handle \r\n)
			if strings.HasSuffix(line, "\r") {
				line = line[:len(line)-1]
			}
			inputLines = append(inputLines, line)
		}
		f.Close()
	}
	inputIdx = 0
	WsEofFlag = "N"
	WsBal = decimal.Zero
	WsYear = 0
	WsCount = 0
	READPARA()
	for !inputDone {
		PROCESSPARA()
	}
	// CLOSE SCHED-FILE (already closed)
	fmt.Printf("SCHEDULES: %s\n", formatPIC99(WsCount))
}

func main() {
	MAINPARA()
}
